    def parse_version(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version_part, _ = version.split('+', 1)
        else:
            version_part = version

        # Split core version from pre-release (at first '-')
        if '-' in version_part:
            core_part, prerelease_part = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return (major, minor, patch, prerelease_identifiers)

    def compare_prerelease(pre1, pre2):
        # If one has pre-release and other doesn't, the one without sorts later
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1  # version without pre-release is greater
        if pre2 is None:
            return -1  # version with pre-release is less

        # Compare identifiers left to right
        for i in range(min(len(pre1), len(pre2))):
            id1 = pre1[i]
            id2 = pre2[i]

            is_num1 = id1.isdigit()
            is_num2 = id2.isdigit()

            if is_num1 and is_num2:
                # Both numeric: compare numerically
                num1 = int(id1)
                num2 = int(id2)
                if num1 < num2:
                    return -1
                if num1 > num2:
                    return 1
            elif is_num1:
                # Numeric vs non-numeric: numeric sorts first
                return -1
            elif is_num2:
                # Non-numeric vs numeric: numeric sorts first
                return 1
            else:
                # Both non-numeric: compare by ASCII order
                if id1 < id2:
                    return -1
                if id1 > id2:
                    return 1

        # All shared identifiers are equal
        if len(pre1) < len(pre2):
            return -1
        if len(pre1) > len(pre2):
            return 1
        return 0

    def sort_key(version_with_index):
        version, original_index = version_with_index
        major, minor, patch, prerelease = parse_version(version)

        # Create a sort key that handles pre-release comparison
        # We return a tuple where we can compare tuples directly
        # For pre-release, we need a special comparison, so we use a wrapper
        return (major, minor, patch, PreReleaseKey(prerelease), original_index)

    class PreReleaseKey:
        def __init__(self, prerelease):
            self.prerelease = prerelease

        def __lt__(self, other):
            result = compare_prerelease(self.prerelease, other.prerelease)
            return result < 0

        def __le__(self, other):
            result = compare_prerelease(self.prerelease, other.prerelease)
            return result <= 0

        def __gt__(self, other):
            result = compare_prerelease(self.prerelease, other.prerelease)
            return result > 0

        def __ge__(self, other):
            result = compare_prerelease(self.prerelease, other.prerelease)
            return result >= 0

        def __eq__(self, other):
            result = compare_prerelease(self.prerelease, other.prerelease)
            return result == 0

        def __ne__(self, other):
            result = compare_prerelease(self.prerelease, other.prerelease)
            return result != 0

    # Add original index to maintain stability
    indexed_versions = [(v, i) for i, v in enumerate(versions)]

    # Sort using the sort key
    sorted_versions = sorted(indexed_versions, key=sort_key)

    # Return just the version strings
    return [v for v, _ in sorted_versions]

